"""Role dashboards: one DashboardBuilder per role."""


def get_dashboard_builder(role: str):
    """Factory: role code -> builder class (imported lazily to avoid import cycles)."""
    from .academic_supervisor import AcademicSupervisorDashboard
    from .coordinator import CoordinatorDashboard
    from .student import StudentDashboard
    from .workplace_supervisor import WorkplaceSupervisorDashboard

    return {
        StudentDashboard.role: StudentDashboard,
        AcademicSupervisorDashboard.role: AcademicSupervisorDashboard,
        WorkplaceSupervisorDashboard.role: WorkplaceSupervisorDashboard,
        CoordinatorDashboard.role: CoordinatorDashboard,
    }[role]
